        vertex = (Vec3sPacked *)(vertexBase + record->vertexOffset0);
        centroidX = vertex->vx;
        centroidY = vertex->vy;
        sumZ = vertex->vz;
        vertex = (Vec3sPacked *)(vertexBase + record->vertexOffset1);
        centroidX += vertex->vx;
        centroidY += vertex->vy;
        sumZ += vertex->vz;
        vertex = (Vec3sPacked *)(vertexBase + record->vertexOffset2);
        centroidX += vertex->vx;
        centroidY += vertex->vy;
        sumZ += vertex->vz;
        centroidX = centroidX / 3;
        centroidY = centroidY / 3;
        sumZ = sumZ / 3;
        g_YasuiLimitSatanSlamFragments[fragmentIdx].posX = centroidX;
        g_YasuiLimitSatanSlamFragments[fragmentIdx].posY = centroidY;
        g_YasuiLimitSatanSlamFragments[fragmentIdx].posZ = sumZ;
        centroidY += 0x8CE;
