/* Appends a new point to a particle trail ring buffer. */
// FUNCTION: FF7 0x00460258
void __cdecl BattleFx_LimitSatanSlamPushTrailPoint(BattleFxLimitSatanSlamTrailRing *ring, int point)
{
    int tail;
    int head;
    int count;

    head = ring->writeIndex;
    tail = ring->startIndex;
    count = ring->count;
    ring->points[head] = point;
    head++;
    count++;
    if (count >= 8) {
        count = 8;
    }
    if (head >= 8) {
        head = 0;
    }
    if (head == tail) {
        tail++;
        count--;
        if (count < 0) {
            count = 0;
        }
        if (tail >= 8) {
            tail = 0;
        }
    }
    ring->writeIndex = head;
    ring->startIndex = tail;
    ring->count = count;
}

