/* Computes homing steering vector toward target entity. */
// FUNCTION: FF7 0x00460760
void __cdecl BattleFx_LimitSatanSlamSteerParticleTowardTarget(YasuiLimitSatanSlamParticle *particle)
{
    VECTOR axis;
    int distance;
    VECTOR dirVec;
    PsxMatrix secondMatrix;
    int turnAngle;
    PsxMatrix matrix;
    int theta;

    particle->deltaX = particle->trailX - particle->posX;
    particle->deltaY = particle->trailY - particle->posY;
    particle->deltaZ = particle->trailZ - particle->posZ;
    distance = NormalizeVectorFixed(&particle->deltaX, &particle->deltaX);
    distance = SqrtToInt(distance);
    if (distance <= particle->arriveDistance) {
        if ((particle->flags & 0x40000000) == 0) {
            particle->flags |= 0x80000000;
        }
    } else {
        particle->flags &= 0x3FFFFFFF;
    }
    particle->steerDistanceCopy = distance;
    if ((particle->flags & 0x8000000) != 0 && distance > particle->distanceLimit) {
        distance = particle->distanceLimit;
    }
    distance = particle->distanceLimit;
    particle->steerDistance = distance;
    theta = ComputeAngleBetweenVectors(&particle->velocity, &particle->delta, &dirVec);
    particle->steerThetaCopy = theta;
    if ((particle->flags & 0x4000000) != 0 && particle->steerThetaLimit < theta) {
        theta = particle->steerThetaLimit;
    }
    particle->steerTheta = theta;
    Gte_BuildAxisAngleMatrix(theta, &matrix, &dirVec);
    TransformVectorToInt32(&matrix, &particle->velocityX, &particle->velocityX);
    *(Int64Pair *)&particle->prevX = *(Int64Pair *)&particle->posX;
    particle->posX += (short)(distance * particle->velocityX >> 0xC);
    particle->posY += (short)(distance * particle->velocityY >> 0xC);
    particle->posZ += (short)(distance * particle->velocityZ >> 0xC);
    if ((particle->flags & 0x10000000) != 0) {
        turnAngle = ComputeAngleBetweenVectors(&particle->launchDir, &particle->velocity, &dirVec);
        Gte_BuildAxisAngleMatrix(turnAngle, &particle->orientation, &dirVec);
    } else {
        dirVec.vx = particle->velocityX;
        dirVec.vy = 0;
        dirVec.vz = particle->velocityZ;
        NormalizeVectorFixed(&dirVec, &dirVec);
        turnAngle = ComputeAngleBetweenVectors(&particle->launchDir, &dirVec, &axis);
        Gte_BuildAxisAngleMatrix(turnAngle, &matrix, &axis);
        turnAngle = ComputeAngleBetweenVectors(&dirVec, &particle->velocity, &axis);
        Gte_BuildAxisAngleMatrix(turnAngle, &secondMatrix, &axis);
        ConcatMatrixPreservingTranslation(&secondMatrix, &matrix, &particle->orientation);
    }
}

