    frame.pointA[1] += g_YasuiLimitSatanSlamTransformMatrix.t[1];
    frame.pointA[2] += g_YasuiLimitSatanSlamTransformMatrix.t[2];
    frame.pointB[0] += g_YasuiLimitSatanSlamTransformMatrix.t[0];
    frame.pointB[1] += g_YasuiLimitSatanSlamTransformMatrix.t[1];
    frame.pointB[2] += g_YasuiLimitSatanSlamTransformMatrix.t[2];
