/* Adjusts actor heights to conform to deformed stage mesh surface. */
// FUNCTION: FF7 0x00460dd4
void __cdecl BattleFx_LimitSatanSlamSetActorHeightsFromMesh(BattleFxLimitSatanSlamMeshState *meshState, int heightScale)
{
    int maxHeight;
    BattleFxSatanSlamActorSurface *surfaceRec;
    int workXMax;
    int actorIdx;
    int heightDelta;
    int minX;
    int stackWords; /* Unreferenced stack padding preserved for VC5 /Od frame size (see lib/codegen.h). */
    int minZ;

    meshState->meshBlob = (int)&g_YasuiLimitSatanSlamWorkingMeshBlob;
    meshState->drawMode = g_YasuiLimitSatanSlamMirrorFlag;
    if (g_YasuiLimitSatanSlamMirrorFlag != 0) {
        minX = g_YasuiLimitSatanSlamTransformMatrix.t[0] - 0x888;
        workXMax = g_YasuiLimitSatanSlamTransformMatrix.t[0] + 0x888;
        minZ = g_YasuiLimitSatanSlamTransformMatrix.t[2] - 0xD58;
        maxHeight = g_YasuiLimitSatanSlamTransformMatrix.t[2] + 0xE70;
    } else {
        minX = g_YasuiLimitSatanSlamTransformMatrix.t[0] - 0x888;
        workXMax = g_YasuiLimitSatanSlamTransformMatrix.t[0] + 0x888;
        minZ = g_YasuiLimitSatanSlamTransformMatrix.t[2] - 0xE70;
        maxHeight = g_YasuiLimitSatanSlamTransformMatrix.t[2] + 0xD58;
    }
    for (actorIdx = 0; actorIdx < 0xA; actorIdx++) {
        surfaceRec = (BattleFxSatanSlamActorSurface *)&g_BattleActorRecords[actorIdx].posX;
        if (surfaceRec->posX >= minX && surfaceRec->posX <= workXMax && surfaceRec->posZ >= minZ && surfaceRec->posZ <= maxHeight) {
            BattleFx_LimitSatanSlamFindMeshSurfaceNearPoint(meshState, surfaceRec);
            if (meshState->hitCount != 0) {
                meshState->height = g_YasuiLimitSatanSlamSavedActorPositions[actorIdx].posY;
                heightDelta = (short)Gte_PlaneHeightDelta((Vec3sPacked *)&meshState->surfaceIndex, (Vec3sPacked *)&meshState->hitX, (BattlePlaneNormal *)&meshState->normalX);
                heightDelta = heightDelta * heightScale >> 0xC;
                g_BattleActorRecords[actorIdx].posY = g_YasuiLimitSatanSlamSavedActorPositions[actorIdx].posY - heightDelta;
                if (heightDelta != 0) {
                    g_BattleActorRecords[actorIdx].drawFlags |= 0x10;
                } else if ((g_YasuiLimitSatanSlamSavedActorFlags[actorIdx] & 0x10) == 0) {
                    g_BattleActorRecords[actorIdx].drawFlags &= 0xEF;
                }
            }
        }
    }
}

/* Queries mesh cell grid to find triangle/quad surface height below a point. */
// FUNCTION: FF7 0x00460fc6
void __cdecl BattleFx_LimitSatanSlamFindMeshSurfaceNearPoint(BattleFxLimitSatanSlamMeshState *meshState, BattleFxSatanSlamActorSurface *surface)
{
    BattleFxSatanSlamMeshGridNode *node;
    int stepEndColUnit;
    int heightSum;
    int isHit;
    int ix;
    int row;
    int gridY;
    int colLo;
    int rowLo;
    int colTemp;
    int rowTemp;
    int curMinCol;
    int rowMin;
    int bestHeight;
    int colIndex8;
    BattleFxShardTriSlot *vertexRec;
    int rowLast;
    char *vertBase;
    int lowCol;
    int clampedHighCol;
    int rowHiTemp;
    int rowHi;

    vertBase = (char *)meshState->meshBlob + 4;
    colIndex8 = surface->posX - g_YasuiLimitSatanSlamTransformMatrix.t[0];
    bestHeight = 1;
    gridY = surface->posZ - g_YasuiLimitSatanSlamTransformMatrix.t[2];
    if (meshState->drawMode != 0) {
        colIndex8 *= -1;
        gridY *= -1;
    }
    meshState->surfaceIndex = colIndex8;
    meshState->height = surface->height;
    meshState->gridY = gridY;
    colIndex8 += 0x888;
    gridY += 0xE70;
    colIndex8 = colIndex8 / 512;
    gridY = gridY / 512;
    curMinCol = colIndex8 - 1;
    stepEndColUnit = colIndex8 + 2;
    rowMin = gridY - 1;
    rowLast = gridY + 2;
    if (curMinCol < 0) {
        lowCol = 0;
    } else {
        if (curMinCol > 8) {
            colLo = 8;
        } else {
            colLo = curMinCol;
        }
        lowCol = colLo;
    }
    curMinCol = lowCol;
    if (stepEndColUnit < 0) {
        clampedHighCol = 0;
    } else {
        if (stepEndColUnit > 8) {
            colTemp = 8;
        } else {
            colTemp = stepEndColUnit;
        }
        clampedHighCol = colTemp;
    }
    stepEndColUnit = clampedHighCol;
    if (rowMin < 0) {
        rowLo = 0;
    } else {
        if (rowMin > 0xD) {
            rowTemp = 0xD;
        } else {
            rowTemp = rowMin;
        }
        rowLo = rowTemp;
    }
    rowMin = rowLo;
    if (rowLast < 0) {
        rowHi = 0;
    } else {
        if (rowLast > 0xD) {
            rowHiTemp = 0xD;
        } else {
            rowHiTemp = rowLast;
        }
        rowHi = rowHiTemp;
    }
    rowLast = rowHi;
    meshState->candidateCount = 0;
    meshState->hitCount = 0;
    for (row = rowMin; row < rowLast; row++) {
        for (ix = curMinCol; ix < stepEndColUnit; ix++) {
            if (g_YasuiLimitSatanSlamMeshGridCells[row][ix] == 1) {
                continue;
            }
            meshState->candidateCount++;
            node = (BattleFxSatanSlamMeshGridNode *)(g_YasuiLimitSatanSlamMeshGridCells[row][ix]);
            for (;;) {
                vertexRec = (BattleFxShardTriSlot *)(node->vertexRecord);
                meshState->v0 = *(SVECTOR *)(vertBase + vertexRec->vertex0Offset);
                meshState->v1 = *(SVECTOR *)(vertBase + vertexRec->vertex1Offset);
                meshState->v2 = *(SVECTOR *)(vertBase + vertexRec->vertex2Offset);
                meshState->v3 = *(SVECTOR *)(vertBase + vertexRec->vertex3Offset);
                isHit = BattleFx_LimitSatanSlamPointInTriangleXZ(&meshState->surface, &meshState->v0, &meshState->v1, &meshState->v2);
                heightSum = meshState->v0y + meshState->v1y + meshState->v2y;
                if (node->isQuad != 0) {
                    if (isHit == 0) {
                        isHit = BattleFx_LimitSatanSlamPointInTriangleXZ(&meshState->surface, &meshState->v1, &meshState->v3, &meshState->v2);
                    }
                    heightSum += meshState->v3y;
                    heightSum = heightSum / 4;
                } else {
                    heightSum = heightSum / 3;
                }
                if (isHit == 1 && heightSum < bestHeight) {
                    meshState->edge1X = meshState->v1x - meshState->v2x;
                    meshState->edge1Y = meshState->v1y - meshState->v2y;
                    meshState->edge1Z = meshState->v1z - meshState->v2z;
                    meshState->edge2X = meshState->v0x - meshState->v1x;
                    meshState->edge2Y = meshState->v0y - meshState->v1y;
                    meshState->edge2Z = meshState->v0z - meshState->v1z;
                    CrossProductFixed12(&meshState->edge1, &meshState->edge2, &meshState->normal);
                    if (meshState->normalY <= 0) {
                        NormalizeVectorFixed(&meshState->normalX, &meshState->normalX);
                        bestHeight = heightSum;
                        meshState->hit = meshState->v0;
                        meshState->hitCount++;
                    }
                }
                if (node->child == 1) {
                    break;
                }
                node = (BattleFxSatanSlamMeshGridNode *)(node->child);
            }
        }
    }
}

/* Tests whether a 2D point lies inside a triangle on the XZ plane. */
// FUNCTION: FF7 0x0046147e
int __cdecl BattleFx_LimitSatanSlamPointInTriangleXZ(SVECTOR *pointA, SVECTOR *pointB, SVECTOR *pointC, SVECTOR *pointD)
{
    int cross2;
    int localEdgeA;
    int cross3;

    localEdgeA = (pointA->vx - pointB->vx) * -(pointC->vz - pointB->vz) + (pointA->vz - pointB->vz) * (pointC->vx - pointB->vx);
    cross2 = (pointA->vx - pointC->vx) * -(pointD->vz - pointC->vz) + (pointA->vz - pointC->vz) * (pointD->vx - pointC->vx);
    cross3 = (pointA->vx - pointD->vx) * -(pointB->vz - pointD->vz) + (pointA->vz - pointD->vz) * (pointB->vx - pointD->vx);
    if (localEdgeA == 0) {
        localEdgeA = 0xFFFFFFFF;
    }
    if (cross2 == 0) {
        cross2 = 0xFFFFFFFF;
    }
    if (cross3 == 0) {
        cross3 = 0xFFFFFFFF;
    }
    localEdgeA = localEdgeA & cross2 & cross3;
    return localEdgeA < 0;
}

